from datetime import datetime
from cronexpr import next_run

cases = [
    ("*/15 * * * *", datetime(2026,3,4,10,7), datetime(2026,3,4,10,15)),
    ("0 9 * * MON-FRI", datetime(2026,3,6,9,0), datetime(2026,3,9,9,0)),
    ("0 0 29 2 *", datetime(2026,3,1), datetime(2028,2,29,0,0)),
    ("30 4 1,15 * 5", datetime(2026,1,1,5,0), datetime(2026,1,2,4,30)),
]
for expr, after, expected in cases:
    got = next_run(expr, after)
    print(expr, got, got == expected)

# seconds
print(next_run("* * * * *", datetime(2026,3,4,12,0,30)))
print(next_run("* * * * *", datetime(2026,3,4,12,0,0)))
try:
    next_run("0 0 30 2 *", datetime(2026,1,1))
except ValueError as e:
    print("raised", e)
try:
    next_run("FRI-MON * * * *", datetime(2026,1,1))
except ValueError as e:
    print("raised", e)
try:
    next_run("60 * * * *", datetime(2026,1,1))
except ValueError as e:
    print("raised", e)
try:
    next_run(5, datetime(2026,1,1))
except TypeError as e:
    print("raised", e)
EOF

