import random
from datetime import datetime, timedelta
import cronexpr

random.seed(1)

def naive(expr, after, horizon_days=800):
    ms, hs, doms, months, dows, domr, dowr = cronexpr._parse(expr)
    cur = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    end = after + timedelta(days=horizon_days)
    while cur <= end:
        dom_ok = cur.day in doms
        dow_ok = ((cur.weekday()+1)%7) in dows
        if domr and dowr: dm = dom_ok or dow_ok
        elif domr: dm = dom_ok
        elif dowr: dm = dow_ok
        else: dm = True
        if cur.month in months and dm and cur.hour in hs and cur.minute in ms:
            return cur
        cur += timedelta(minutes=1)
    return None

def rand_field(mn, mx, names=None):
    items=[]
    for _ in range(random.randint(1,3)):
        kind=random.choice(["*","n","r","ns","rs","st"])
        if kind=="*": items.append("*")
        elif kind=="n": items.append(str(random.randint(mn,mx)))
        elif kind=="r":
            a=random.randint(mn,mx); b=random.randint(a,mx); items.append(f"{a}-{b}")
        elif kind=="ns": items.append(f"{random.randint(mn,mx)}/{random.randint(1,7)}")
        elif kind=="rs":
            a=random.randint(mn,mx); b=random.randint(a,mx); items.append(f"{a}-{b}/{random.randint(1,7)}")
        else: items.append(f"*/{random.randint(1,7)}")
    return ",".join(items)

bad=0
for i in range(300):
    expr = " ".join([
        rand_field(0,59), rand_field(0,23), rand_field(1,31),
        rand_field(1,12), rand_field(0,7),
    ])
    after = datetime(2026,1,1) + timedelta(minutes=random.randint(0, 500000))
    try:
        got = cronexpr.next_run(expr, after)
    except ValueError:
        got = None
    exp = naive(expr, after)
    if exp is not None and got != exp:
        print("MISMATCH", expr, after, got, exp); bad+=1
    if exp is None and got is not None and got <= after + timedelta(days=800):
        print("MISMATCH2", expr, after, got, exp); bad+=1
print("done bad=", bad)
